# Generated by manage.py generate_test_cases.
"""Exercise standalone rooms and preservation of independent conference history."""

from django.db.models.deletion import ProtectedError

from bloomerp.models.communication.conferencing import ConferenceRoom, ConferenceSession
from bloomerp.models.communication.instant_messaging import IMConversation
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)


class TestConferenceRoomModel(BloomerpModelTestCase):
    model = ConferenceRoom

    def get_test_scenarios(self) -> list[ModelScenario[ConferenceRoom]]:
        """Cover optional IM context and protection of retained call history."""
        return [
            ModelScenario(
                name="Standalone room can be archived",
                create_args={"title": "Planning"},
                update_args={"archived": True},
                update_validators=self.is_archived,
            ),
            ModelScenario(
                name="Deleting chat preserves conference room",
                create_args={"title": "Chat call"},
                post_create=self.delete_context,
                create_validators=self.is_independent,
            ),
            ModelScenario(
                name="Room with call history cannot be deleted",
                create_args={"title": "Historical room"},
                post_create=self.add_session,
                expected_exceptions=[ExpectedModelException("delete", ProtectedError)],
            ),
        ]

    def is_archived(self, room: ConferenceRoom) -> bool:
        """Confirm room archival is persisted."""
        return room.archived

    def is_independent(self, room: ConferenceRoom) -> bool:
        """Confirm the room survives removal of its conversation context."""
        room.refresh_from_db()
        return room.conversation_id is None

    def delete_context(self, room: ConferenceRoom) -> None:
        """Attach and delete an IM context while retaining the meeting space."""
        chat = IMConversation.objects.create(kind="group")
        room.conversation = chat
        room.save()
        chat.delete()

    def add_session(self, room: ConferenceRoom) -> None:
        """Create call history that must survive accidental room deletion."""
        ConferenceSession.objects.create(room=room)
